/* =====================================================================
 * SwachLens — i18n engine: 29 Indian state languages
 * ---------------------------------------------------------------------
 * Provides:
 *   - SW_LANGS : the 29 supported languages (code + native name)
 *   - SW_I18N  : translation dictionaries keyed by language code
 *   - t(key)   : global lookup with English fallback
 *   - Language dropdown injection into [data-lang-switch] containers
 *   - data-i18n attribute handling for static HTML
 *   - localStorage persistence (swachlens.lang)
 *
 * Usage in HTML:
 *   <div data-lang-switch></div>           → dropdown rendered here
 *   <h1 data-i18n="hero.lead">...</h1>     → text replaced on apply
 *   <input data-i18n-ph="auth.phEmail">    → placeholder replaced
 *   <button data-i18n-title="...">         → title attr replaced
 *
 * Usage in JS:
 *   t('nav.login') → "Log in"
 * ===================================================================== */
