      'nav.dashboard': 'டாஷ்போர்டைத் திற →',
      'nav.backHome': '← முகப்புக்குத் திரும்பு',
      'nav.skip': 'உள்ளடக்கத்திற்குச் செல்',
      'nav.theme': 'லைட் / டார்க் முறை',
      'common.reportWaste': 'கழிவைப் புகாரளி',
      'common.explore': 'ஸ்வச்லென்ஸை ஆராயுங்கள்',
      'hero.eyebrow': 'நகர நிகம் · ஸ்மார்ட் தூய்மை',
      'hero.lead': 'நிறைந்த தொட்டி, சட்டவிரோதக் குப்பை, தவறிய எடுப்பு — பாருங்கள். புகைப்படம் எடுங்கள், ஸ்வச்லென்ஸ் சரியான தூய்மைக் குழுவுக்கு அனுப்பி, வேலை முடிந்ததா என சரிபார்க்கும். குடிமகன் முதல் ஒவ்வொரு தெரு வரை ஒரு குடிமைச் சுழற்சி.',
      'hero.floatA': 'புகார் பெறப்பட்டது',
      'hero.floatA2': 'புகைப்படம் + இடம் குறிக்கப்பட்டது',
      'hero.floatB': 'AI குழுவை அனுப்பியது',
      'hero.floatB2': 'வடக்கு மண்டலம் · 2 நிமிடத்திற்கு முன்',
      'hero.floatC': 'தூய்மை சரிபார்க்கப்பட்டது',
      'hero.floatC2': 'தீர்க்கப்பட்டது · சரியான நேரத்தில்',
      'sys.kicker': 'ஸ்வச்லென்ஸ்',
      'sys.title': 'ஒரு சரிபார்க்கப்பட்ட சுழற்சி,<br>ஆரம்பம் முதல் இறுதி வரை.',
      'sys.lead': 'ஒவ்வொரு புகாரும் ஒரே குழாய் வழியே செல்கிறது — குடிமகனின் புகைப்படம் முதல் சரிபார்க்கப்பட்ட, பதிவான தூய்மை வரை. ஒவ்வொரு படிக்கும் ஒரு உரிமையாளர் இருப்பதால் எதுவும் தவறவிடப்படாது.',
      'roles.kicker': 'உங்களுக்காக',
      'roles.title': 'இரண்டு பாத்திரங்கள், ஒரு தூய்மையான நகரம்.',
      'roles.lead': 'சுழற்சியில் நீங்கள் எங்கு இருக்கிறீர்கள் எனத் தேர்ந்தெடுங்கள். ஒவ்வொரு பாத்திரத்தின் பணிப்போக்கையும் பார்த்து அங்கிருந்தே உள்நுழையுங்கள்.',
      'gis.kicker': 'லைவ் GIS',
      'gis.title': 'நகரம், <span class="lv-em">லைவ் வரைபடம்.</span>',
      'gis.lead': 'தொட்டிகள் தங்கள் நிரப்பு அளவை அறிவிக்கும். லாரிகள் தங்கள் பாதையை ஒளிபரப்பும். நீங்கள் கை உயர்த்தினால் சுழற்சி உடனே திரும்பும்.',
