      'imp.kicker': 'நிஜ தாக்கம்',
      'imp.title': 'நிஜ மனிதர்கள். <span class="lv-em">நிஜ தாக்கம்.</span>',
      'imp.lead': 'குடிமக்களின் புகார்களை ஸ்வச்லென்ஸ் அளவிடக்கூடிய செயலாக்க மாற்றுவதைப் பாருங்கள்.',
      'cta.kicker': 'இன்றே தொடங்குங்கள்',
      'cta.title': 'ஒவ்வொரு புகாரும் கணக்கில் வரட்டும்.',
      'cta.lead': 'நீங்கள் விரும்பும் இடத்தைத் தேர்ந்தெடுத்து சுழற்சியில் நுழையுங்கள். குடிமக்கள், குழுக்கள், நகராட்சிகளுக்கு இலவசம்.',
      'auth.kicker': 'ஒரு தளம் · இரண்டு பாத்திரங்கள்',
      'auth.title1': 'உங்கள் பாத்திரத்தைத் தேர்வு செய்க:',
      'auth.title2': 'உங்கள் கணக்கை உருவாக்குங்கள்:',
