      'auth.lead2': 'பாத்திரத்தைத் தேர்வு செய்து, கடவுச்சொல்லை அமைத்து, குடிமைச் சுழற்சியில் நுழையுங்கள்.',
      'auth.roleCit': 'குடிமகன்',
