      'auth.roleEmpSub': 'தூய்மைக் குழு · பகுதி குழுக்கள்',
      'auth.citTitle': 'கழிவைப் பாருங்கள். புகாரளியுங்கள்.<br>மறைவதைப் பாருங்கள்.',
      'auth.citBody': 'உங்கள் புகாருக்கும் எடுப்புக்கும் உண்மையான உரிமையாளர் உண்டு — சுத்தம் செய்யும் குழுவும் அதை நிரூபிக்கும் சரிபார்ப்பும்.',
