      'cta.kicker': 'આજે જ શરૂ કરો',
      'cta.title': 'દરેક જાણને મહત્ત્વ આપો.',
      'cta.lead': 'તમને અનુકૂળ સ્થાન પસંદ કરો અને લૂપમાં પ્રવેશો. નાગરિકો, ટીમો અને મ્યુનિસિપાલિટી માટે મફત.',
