      'common.reportWaste': 'ತ್ಯಾಜ್ಯ ವರದಿ ಮಾಡಿ',
      'common.explore': 'ಸ್ವಚ್‌ಲೆನ್ಸ್ ಅನ್ವೇಷಿಸಿ',
      'hero.eyebrow': 'ನಗರ ನಿಗಮ · ಸ್ಮಾರ್ಟ್ ಸ್ವಚ್ಛತೆ',
      'hero.lead': 'ತುಂಬಿದ ಬಿನ್, ಕಾನೂನುಬಾಹಿರ ಡಂಪ್, ತಪ್ಪಿದ ಪಿಕಪ್ ನೋಡಿ. ಫೋಟೋ ತೆಗೆಯಿರಿ — ಸ್ವಚ್‌ಲೆನ್ಸ್ ಅದನ್ನು ಸರಿಯಾದ ಸ್ವಚ್ಛತಾ ತಂಡಕ್ಕೆ ರವಾನಿಸಿ, ಕೆಲಸ ನಿಜವಾಗಿ ಆಗಿದೆಯೇ ಎಂದು ಪರಿಶೀಲಿಸುತ್ತದೆ. ನಾಗರಿಕರಿಂದ ಪ್ರತಿ ಬೀದಿಯವರೆಗೆ ಒಂದೇ ನಾಗರಿಕ ಚಕ್ರ.',
      'hero.floatA': 'ವರದಿ ಸ್ವೀಕೃತ',
      'hero.floatA2': 'ಫೋಟೋ + ಸ್ಥಳ ಟ್ಯಾಗ್ ಆಗಿದೆ',
      'hero.floatB': 'AI ತಂಡವನ್ನು ಕಳುಹಿಸಿದೆ',
      'hero.floatB2': 'ಉತ್ತರ ವಲಯ · 2 ನಿಮಿಷದ ಹಿಂದೆ',
      'hero.floatC': 'ಸ್ವಚ್ಛತೆ ಪರಿಶೀಲಿಸಲಾಗಿದೆ',
      'hero.floatC2': 'ಪರಿಹರಿಸಲಾಗಿದೆ · ಸಮಯಕ್ಕೆ',
      'sys.kicker': 'ಸ್ವಚ್‌ಲೆನ್ಸ್',
      'sys.title': 'ಒಂದು ಪರಿಶೀಲಿತ ಚಕ್ರ,<br>ಆರಂಭದಿಂದ ಕೊನೆಯವರೆಗೆ.',
      'sys.lead': 'ಪ್ರತಿ ವರದಿಯು ಒಂದೇ ಪೈಪ್‌ಲೈನ್‌ಗೆ ಪ್ರವೇಶಿಸುತ್ತದೆ — ನಾಗರಿಕರ ಫೋಟೋದಿಂದ ಪರಿಶೀಲಿತ, ದಾಖಲಾದ ಸ್ವಚ್ಛತೆಯವರೆಗೆ. ಪ್ರತಿ ಹಂತಕ್ಕೂ ಒಬ್ಬ ಮಾಲೀಕ ಇರುವುದರಿಂದ ಏನೂ ಜಾರುವುದಿಲ್ಲ.',
      'roles.kicker': 'ನಿಮಗಾಗಿ',
      'roles.title': 'ಎರಡು ಪಾತ್ರಗಳು, ಒಂದು ಸ್ವಚ್ಛ ನಗರ.',
      'roles.lead': 'ಚಕ್ರದಲ್ಲಿ ನೀವು ಎಲ್ಲಿದ್ದೀರಿ ಎಂದು ಆಯ್ಕೆ ಮಾಡಿ. ಪ್ರತಿ ಪಾತ್ರದ ಸ್ವಂತ ವರ್ಕ್‌ಫ್ಲೋ ನೋಡಿ ಅಲ್ಲಿಂದಲೇ ಸೈನ್ ಇನ್ ಮಾಡಿ.',
      'gis.kicker': 'ಲೈವ್ GIS',
      'gis.title': 'ನಗರ, <span class="lv-em">ಲೈವ್ ನಕ್ಷೆ.</span>',
