      'common.reportWaste': 'ਕੂੜੇ ਦੀ ਰਿਪੋਰਟ ਕਰੋ',
      'common.explore': 'ਸਵੱਛ ਲੈਂਸ ਦੀ ਪੜਚੋਲ ਕਰੋ',
      'hero.eyebrow': 'ਨਗਰ ਨਿਗਮ · ਸਮਾਰਟ ਸਫ਼ਾਈ',
      'hero.lead': 'ਭਰਿਆ ਡੱਬਾ, ਗੈਰ-ਕਾਨੂੰਨੀ ਡੰਪ, ਜਾਂ ਖੁੰਝਿਆ ਪਿਕਅੱਪ ਦੇਖੋ। ਫੋਟੋ ਲਵੋ — ਸਵੱਛ ਲੈਂਸ ਇਸ ਨੂੰ ਸਹੀ ਸਫ਼ਾਈ ਟੀਮ ਕੋਲ ਭੇਜਦਾ ਹੈ ਅਤੇ ਕੰਮ ਅਸਲ ਵਿੱਚ ਹੋਇਆ ਹੈ ਜਾਂ ਨਹੀਂ ਪਰਖਦਾ ਹੈ। ਨਾਗਰਿਕ ਤੋਂ ਲੈ ਕੇ ਹਰ ਗਲੀ ਤੱਕ ਇੱਕ ਨਾਗਰਿਕ ਚੱਕਰ।',
