      'hero.floatB2': 'ਉੱਤਰੀ ਜ਼ੋਨ · 2 ਮਿੰਟ ਪਹਿਲਾਂ',
      'hero.floatC': 'ਸਫ਼ਾਈ ਤਸਦੀਕ ਹੋਈ',
      'hero.floatC2': 'ਹੱਲ ਹੋਇਆ · ਸਮੇਂ ਸਿਰ',
      'sys.kicker': 'ਸਵੱਛ ਲੈਂਸ',
      'sys.title': 'ਇੱਕ ਤਸਦੀਕੀ ਚੱਕਰ,<br>ਸ਼ੁਰੂ ਤੋਂ ਅੰਤ ਤੱਕ।',
      'sys.lead': 'ਹਰ ਰਿਪੋਰਟ ਇੱਕੋ ਪਾਈਪਲਾਈਨ ਵਿੱਚ ਦਾਖਲ ਹੁੰਦੀ ਹੈ — ਨਾਗਰਿਕ ਦੀ ਫੋਟੋ ਤੋਂ ਲੈ ਕੇ ਤਸਦੀਕੀ, ਦਰਜ ਸਫ਼ਾਈ ਤੱਕ। ਕੁਝ ਵੀ ਖੁੰਝਦਾ ਨਹੀਂ ਕਿਉਂਕਿ ਹਰ ਕਦਮ ਦਾ ਇੱਕ ਮਾਲਕ ਹੈ।',
