      'imp.kicker': 'ನಿಜವಾಯಿನ ಪ್ರಭಾವ',
      'imp.title': 'ನಿಜವಾಯಿನ ಜನಕುಲು. <span class="lv-em">ನಿಜವಾಯಿನ ಪ್ರಭಾವ.</span>',
      'imp.lead': 'ಸ್ವಚ್ ಲೆನ್ಸ್ ನಾಗರಿಕ ರಿಪೋರ್ಟ್ ಲೆನ್ ಮಾಪನ ಆಪಿನ ಕ್ರಮೊಗ್ ಏಂಚ ಬದಲ್ಪಾವು ಪಂದ್ ತೂಲೆ.',
      'cta.kicker': 'ಇನಿ ಉಂದೇ ಸುರು ಮಲ್ಪುಲೆ',
      'cta.title': 'ಪ್ರತಿ ರಿಪೋರ್ಟ್ ಗ್ ಅರ್ಥ ಕೊರುಲೆ.',
      'cta.lead': 'ಇರ್ನ ಜಾಗೆ ಆಯ್ಕೆ ಮಲ್ತ್ದ್ ಚಕ್ರೊಗ್ ಸೇರುಲೆ. ನಾಗರಿಕೆರ್, ಟೀಂ ಬೊಕ್ಕ ನಗರ ನಿಗಮಗ್ ಮುಕ್ತ.',
      'auth.kicker': 'ಒಂಜಿ ಪ್ಲಾಟ್‍ಫಾರ್ಮ್ · ರಡ್ಡ್ ಪಾತ್ರೊ',
