      'auth.lead2': 'ಪಾತ್ರೊ ಆಯ್ಕೆ ಮಲ್ತ್ದ್, ಪಾಸ್‍ವರ್ಡ್ ದೀದ್ ನಾಗರಿಕ ಚಕ್ರೊಗ್ ಸೇರುಲೆ.',
